/* =====================================================================
 * drm.c -- Cob Enterprise license verification (verify-only)
 * See include/drm.h for the file format. Uses Monocypher (vendor/).
 * Compiled only when building with ENTERPRISE=1.
 * ===================================================================== */
#include "drm.h"
#include "monocypher.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifndef COB_LIC_NO_EMBEDDED_KEYS
#include "drm_pubkey.h"   /* generated by `cob_sign keygen`: COB_LIC_KEYS[] */
#endif

const char *cob_lic_strerror(int code) {
    switch (code) {
    case COB_LIC_OK:            return "ok";
    case COB_LIC_NOT_FOUND:     return "no license file found";
    case COB_LIC_MALFORMED:     return "license file is malformed";
    case COB_LIC_UNKNOWN_KEY:   return "license was signed with a key this build does not know";
    case COB_LIC_BAD_SIGNATURE: return "license signature is invalid (file edited or not issued by Pixel Pulse Labs)";
    case COB_LIC_EXPIRED:       return "license has expired";
    default:                    return "unknown license error";
    }
}

/* ---- base64 (standard alphabet, whitespace ignored) ---- */
static int b64val(int c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '+') return 62;
    if (c == '/') return 63;
    return -1;
}

static int b64decode(const char *s, size_t n, uint8_t *out, size_t out_cap, size_t *out_len) {
    uint32_t acc = 0; int bits = 0; size_t o = 0; size_t i;
    for (i = 0; i < n; i++) {
        int v;
        char c = s[i];
        if (c == '=' || c == '\n' || c == '\r' || c == ' ' || c == '\t') continue;
        v = b64val((unsigned char)c);
        if (v < 0) return -1;
        acc = (acc << 6) | (uint32_t)v; bits += 6;
        if (bits >= 8) {
            bits -= 8;
            if (o >= out_cap) return -1;
            out[o++] = (uint8_t)((acc >> bits) & 0xFF);
        }
    }
    *out_len = o;
    return 0;
}

/* ---- date helpers (days since 1970-01-01, proleptic Gregorian) ---- */
static long days_from_civil(int y, int m, int d) {
    long era, yoe, doy, doe;
    y -= m <= 2;
    era = (y >= 0 ? y : y - 399) / 400;
    yoe = y - era * 400;
    doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
    doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + doe - 719468;
}

static int parse_date_end_of_day(const char *s, time_t *out) {
    int y, m, d; char extra;
    if (sscanf(s, "%4d-%2d-%2d%c", &y, &m, &d, &extra) != 3) return -1;
    if (y < 1970 || y > 9999 || m < 1 || m > 12 || d < 1 || d > 31) return -1;
    *out = (time_t)(days_from_civil(y, m, d) * 86400L + 86399L);   /* valid through that day, UTC */
    return 0;
}

static void copy_field(char *dst, size_t cap, const char *src) {
    size_t n = strlen(src);
    if (n >= cap) n = cap - 1;
    memcpy(dst, src, n);
    dst[n] = '\0';
}

/* Parse the key=value lines of an (already verified, or key_id-only) payload. */
static int parse_payload(const char *p, size_t n, CobLicense *lic) {
    size_t i = 0;
    int line_no = 0;
    memset(lic, 0, sizeof(*lic));
    lic->key_id = -1;
    while (i < n) {
        char line[512]; size_t l = 0; char *eq;
        while (i < n && p[i] != '\n') { if (l + 1 < sizeof(line)) line[l++] = p[i]; i++; }
        i++;                       /* skip \n */
        line[l] = '\0';
        if (line_no++ == 0) { if (strcmp(line, "COBLIC1") != 0) return -1; continue; }
        if (l == 0) continue;
        eq = strchr(line, '=');
        if (!eq) return -1;
        *eq = '\0';
        if      (!strcmp(line, "customer")) copy_field(lic->customer, sizeof lic->customer, eq + 1);
        else if (!strcmp(line, "issued"))   copy_field(lic->issued,   sizeof lic->issued,   eq + 1);
        else if (!strcmp(line, "expires"))  copy_field(lic->expires,  sizeof lic->expires,  eq + 1);
        else if (!strcmp(line, "features")) copy_field(lic->features, sizeof lic->features, eq + 1);
        else if (!strcmp(line, "seats"))    lic->seats  = atoi(eq + 1);
        else if (!strcmp(line, "key_id"))   lic->key_id = atoi(eq + 1);
        /* unknown keys are ignored (they are covered by the signature anyway) */
    }
    return line_no > 0 ? 0 : -1;
}

/* Split text into (payload incl. its trailing \n) and (base64 signature). */
static int split_license(const char *t, size_t n, size_t *payload_len, const char **sig, size_t *sig_len) {
    size_t i;
    for (i = 0; i + 4 <= n; i++) {
        if ((i == 0 || t[i - 1] == '\n') && t[i] == '-' && t[i + 1] == '-' && t[i + 2] == '-' &&
            (t[i + 3] == '\n' || i + 3 == n)) {
            *payload_len = i;
            *sig = t + i + 4 <= t + n ? t + i + 4 : t + n;
            *sig_len = (size_t)((t + n) - *sig);
            return i > 0 ? 0 : -1;
        }
    }
    return -1;
}

/* Core: caller supplies the key lookup via a callback-free design:
 * pubkey != NULL -> use it; (embedded-key path is in cob_lic_load). */
static int verify_with_key(const char *t, size_t n, const uint8_t *pubkey, CobLicense *out) {
    size_t payload_len, sig_len, got = 0; const char *sig_b64;
    uint8_t sig[64];
    CobLicense lic;
    time_t now;
    if (split_license(t, n, &payload_len, &sig_b64, &sig_len) != 0) return COB_LIC_MALFORMED;
    if (b64decode(sig_b64, sig_len, sig, sizeof sig, &got) != 0 || got != 64) return COB_LIC_MALFORMED;
    if (crypto_eddsa_check(sig, pubkey, (const uint8_t *)t, payload_len) != 0) return COB_LIC_BAD_SIGNATURE;
    if (parse_payload(t, payload_len, &lic) != 0) return COB_LIC_MALFORMED;
    if (strcmp(lic.expires, "never") == 0 || lic.expires[0] == '\0') {
        lic.expires_at = 0;
    } else if (parse_date_end_of_day(lic.expires, &lic.expires_at) != 0) {
        return COB_LIC_MALFORMED;
    }
    if (out) *out = lic;
    now = time(NULL);
    if (lic.expires_at != 0 && now > lic.expires_at) return COB_LIC_EXPIRED;
    return COB_LIC_OK;
}

/* Strip every '\r' so a license mangled by CRLF conversion (email,
 * Windows editors) still verifies: the signer only ever writes LF. */
static char *normalize_lf(const char *t, size_t n, size_t *out_n) {
    char *c = (char *)malloc(n + 1); size_t i, o = 0;
    if (!c) return NULL;
    for (i = 0; i < n; i++) if (t[i] != '\r') c[o++] = t[i];
    c[o] = '\0'; *out_n = o;
    return c;
}

int cob_lic_verify_text(const char *text, size_t len, const uint8_t pubkey[32], CobLicense *out) {
    size_t n; int rc;
    char *c = normalize_lf(text, len, &n);
    if (!c) return COB_LIC_MALFORMED;
    rc = verify_with_key(c, n, pubkey, out);
    free(c);
    return rc;
}

#ifndef COB_LIC_NO_EMBEDDED_KEYS

static CobLicense g_current;
static int g_loaded = 0;

static char *read_file(const char *path, size_t *n) {
    FILE *f = fopen(path, "rb"); char *buf; long sz;
    if (!f) return NULL;
    if (fseek(f, 0, SEEK_END) != 0 || (sz = ftell(f)) < 0 || sz > 65536) { fclose(f); return NULL; }
    rewind(f);
    buf = (char *)malloc((size_t)sz + 1);
    if (!buf) { fclose(f); return NULL; }
    *n = fread(buf, 1, (size_t)sz, f);
    buf[*n] = '\0';
    fclose(f);
    return buf;
}

static int try_path(const char *path, CobLicense *out, int *found) {
    size_t n = 0, m = 0; char *raw, *c; int rc, key_id = -1; size_t i;
    CobLicense probe;
    raw = read_file(path, &n);
    if (!raw) return COB_LIC_NOT_FOUND;
    *found = 1;
    c = normalize_lf(raw, n, &m);
    free(raw);
    if (!c) return COB_LIC_MALFORMED;
    {   /* pick the key by key_id (untrusted until the signature checks out) */
        size_t pl, sl; const char *sg;
        if (split_license(c, m, &pl, &sg, &sl) != 0 || parse_payload(c, pl, &probe) != 0) { free(c); return COB_LIC_MALFORMED; }
        key_id = probe.key_id;
    }
    rc = COB_LIC_UNKNOWN_KEY;
    for (i = 0; i < sizeof(COB_LIC_KEYS) / sizeof(COB_LIC_KEYS[0]); i++) {
        if (COB_LIC_KEYS[i].id == key_id) { rc = verify_with_key(c, m, COB_LIC_KEYS[i].key, out); break; }
    }
    free(c);
    return rc;
}

int cob_lic_load(const char *explicit_path, CobLicense *out) {
    char buf[1024]; const char *env; int found = 0, rc;
    CobLicense tmp;
    if (!out) out = &tmp;
    if (explicit_path) {
        rc = try_path(explicit_path, out, &found);
        return rc;
    }
    env = getenv("COB_LICENSE");
    if (env && *env) { rc = try_path(env, out, &found); if (found) return rc; }
    rc = try_path("cob.lic", out, &found); if (found) return rc;
#ifdef _WIN32
    env = getenv("APPDATA");
    if (env && *env) { snprintf(buf, sizeof buf, "%s\\cob\\cob.lic", env); rc = try_path(buf, out, &found); if (found) return rc; }
#else
    env = getenv("HOME");
    if (env && *env) { snprintf(buf, sizeof buf, "%s/.config/cob/cob.lic", env); rc = try_path(buf, out, &found); if (found) return rc; }
    rc = try_path("/etc/cob/cob.lic", out, &found); if (found) return rc;
#endif
    return COB_LIC_NOT_FOUND;
}

int cob_lic_require(const char *tool) {
    int rc = cob_lic_load(NULL, &g_current);
    if (rc == COB_LIC_OK) { g_loaded = 1; return 0; }
    fprintf(stderr,
        "[%s] error: this is a Cob Enterprise build and it needs a valid license.\n"
        "  reason: %s\n", tool, cob_lic_strerror(rc));
    if (rc == COB_LIC_EXPIRED)
        fprintf(stderr, "  license for \"%s\" expired on %s\n", g_current.customer, g_current.expires);
    fprintf(stderr,
        "  Looked for: $COB_LICENSE, ./cob.lic, per-user config dir, /etc/cob/cob.lic\n"
        "  The free build needs no license: https://cob.pixel-pulse.dev/download.html\n");
    return 1;
}

const CobLicense *cob_lic_current(void) { return g_loaded ? &g_current : NULL; }

int cob_feature_enabled(const char *feature) {
    const char *p; size_t fl;
    if (!g_loaded || !feature || !*feature) return 0;
    p = g_current.features; fl = strlen(feature);
    if (strcmp(p, "*") == 0) return 1;
    while (*p) {
        const char *e = strchr(p, ',');
        size_t l = e ? (size_t)(e - p) : strlen(p);
        if (l == fl && strncmp(p, feature, fl) == 0) return 1;
        if (!e) break;
        p = e + 1;
    }
    return 0;
}
#endif /* COB_LIC_NO_EMBEDDED_KEYS */
